// Asset manifest. Files are generated by scripts/build-assets.mjs into public/assets:
//   villagers/<id>/<pose>.webp   (512px)
//   decor/<id>.webp              (512px)
//   icons/<id>.webp              (256px)
//   backgrounds/<id>.webp        (1024px)
// Every path is prefixed with import.meta.env.BASE_URL so it works under any deploy base.

export type Pose = 'idle' | 'happy' | 'excited' | 'surprised' | 'sleepy' | 'thinking';

export interface Villager {
  id: string;
  name: string;
  /** Kana-only name shown to the child (the Latin `name` stays internal). */
  nameJa: string;
  species: string;
  poses: Record<Pose, string>;
}

const BASE = import.meta.env.BASE_URL;
const url = (rel: string) => `${BASE}assets/${rel}`;

export const POSES: readonly Pose[] = ['idle', 'happy', 'excited', 'surprised', 'sleepy', 'thinking'];

const villager = (id: string, name: string, nameJa: string, species: string): Villager => ({
  id,
  name,
  nameJa,
  species,
  poses: Object.fromEntries(POSES.map((p) => [p, url(`villagers/${id}/${p}.webp`)])) as Record<Pose, string>,
});

export const VILLAGERS: Villager[] = [
  villager('mimi', 'Mimi', 'ミミ', 'cat'),
  villager('hana', 'Hana', 'ハナ', 'dog'),
  villager('momo', 'Momo', 'モモ', 'rabbit'),
  villager('penta', 'Penta', 'ペンタ', 'penguin'),
  villager('sora', 'Sora', 'ソラ', 'bear'),
  villager('rin', 'Rin', 'リン', 'squirrel'),
  villager('keroppi', 'Pyon', 'ぴょん', 'frog'),
  villager('mei', 'Mei', 'メイ', 'deer'),
  villager('muu', 'Muu', 'ムー', 'cow'),
  villager('piyo', 'Piyo', 'ピヨ', 'bird'),
  villager('momo_chan', 'Fuwa', 'ふわ', 'sheep'),
];

const list = (dir: string, ids: string[]) => ids.map((id) => ({ id, src: url(`${dir}/${id}.webp`) }));

const DECOR_NAMES: [string, string][] = [
  ['apple_tree', 'りんごのき'], ['beach_umbrella', 'ビーチパラソル'], ['birdhouse', 'とりのおうち'],
  ['campfire', 'たきび'], ['festive_bunting', 'はたかざり'], ['flower_arch', 'はなのアーチ'],
  ['flower_planter', 'はなのプランター'], ['fountain', 'ふんすい'], ['hay_bale', 'ほしくさ'],
  ['market_stall', 'いちばのおみせ'], ['mushroom_cluster', 'きのこ'], ['picnic_basket', 'ピクニックバスケット'],
  ['red_mailbox', 'あかいポスト'], ['stepping_stones', 'ふみいし'], ['street_lantern', 'がいとう'],
  ['treasure_chest', 'たからばこ'], ['vegetable_crate', 'やさいのはこ'], ['village_well', 'いど'],
  ['watering_can', 'じょうろ'], ['windmill_ornament', 'かざぐるま'], ['wooden_barrel', 'たる'],
  ['wooden_bench', 'ベンチ'], ['wooden_bridge', 'きのはし'], ['wooden_signpost', 'あんないばん'],
];

/** Decorations; `nameJa` is the kana-only name shown to the child. */
export const DECOR: { id: string; src: string; nameJa: string }[] = DECOR_NAMES.map(([id, nameJa]) => ({
  id,
  src: url(`decor/${id}.webp`),
  nameJa,
}));

const ICON_IDS = [
  'camera', 'check_badge', 'coin', 'envelope', 'fishing_rod', 'food_bowl', 'gem', 'gift_box',
  'heart', 'home', 'leaf', 'map_pin', 'moon', 'music_note', 'paint_palette', 'settings_gear',
  'shopping_basket', 'speech_bubble', 'star', 'sun', 'trophy', 'water_droplet',
  'watering_can_icon', 'wooden_sign_icon',
];
export const ICONS: Record<string, string> = Object.fromEntries(
  ICON_IDS.map((id) => [id, url(`icons/${id}.webp`)]),
);

export const BACKGROUNDS: { id: string; src: string }[] = list('backgrounds', [
  'flower_meadow_village', 'forest_village', 'seaside_village', 'snowy_village',
  'sunny_village_square', 'sunset_village',
]);

/** Twemoji picture for a word, from public/assets/emoji/<imageId>.svg. */
export const emojiSrc = (imageId: string): string => url(`emoji/${imageId}.svg`);
